/* From Uiverse.io by alexmaracinaru - Tags: button */
.__UIV_SCOPE__ .cta {
 position: relative;
 margin: auto;
 padding: 12px 18px;
 transition: all 0.2s ease;
 border: none;
 background: none;
}

.__UIV_SCOPE__ .cta:before {
 content: "";
 position: absolute;
 top: 0;
 left: 0;
 display: block;
 border-radius: 50px;
 background: #b1dae7;
 width: 45px;
 height: 45px;
 transition: all 0.3s ease;
}

.__UIV_SCOPE__ .cta span {
 position: relative;
 font-family: "Ubuntu", sans-serif;
 font-size: 18px;
 font-weight: 700;
 letter-spacing: 0.05em;
 color: #234567;
}

.__UIV_SCOPE__ .cta svg {
 position: relative;
 top: 0;
 margin-left: 10px;
 fill: none;
 stroke-linecap: round;
 stroke-linejoin: round;
 stroke: #234567;
 stroke-width: 2;
 transform: translateX(-5px);
 transition: all 0.3s ease;
}

.__UIV_SCOPE__ .cta:hover:before {
 width: 100%;
 background: #b1dae7;
}

.__UIV_SCOPE__ .cta:hover svg {
 transform: translateX(0);
}

.__UIV_SCOPE__ .cta:active {
 transform: scale(0.95);
}
